<template><PageContainer><PageHeader eyebrow="SCR-MON-006" title="Alertes monitoring" description="Signaux actifs, seuils et resolution operationnelle."><template #actions><RouterLink class="mon-pill" to="/app/monitoring"><ArrowLeft/>Retour</RouterLink><button class="mon-btn mon-btn--primary" @click="store.chargerAlertes"><RefreshCw/>Actualiser</button></template></PageHeader>
<SectionBlock v-if="canCreate" title="Creer une alerte" description="Formulaire borne sur le contrat backend officiel MON-09."><form class="mon-grid" @submit.prevent="create"><label class="mon-field"><span>Identifiant</span><input v-model="form.alertId" maxlength="160" :aria-invalid="!!errors.alertId"/><small v-if="errors.alertId" class="mon-error">{{errors.alertId}}</small></label><label class="mon-field"><span>Indicateur</span><input v-model="form.indicateur" maxlength="160" :aria-invalid="!!errors.indicateur"/></label><label class="mon-field"><span>Warning</span><input v-model.number="form.warning" type="number" min="0" step="any"/></label><label class="mon-field"><span>Critical</span><input v-model.number="form.critical" type="number" min="0" step="any"/></label><label class="mon-field"><span>Unite</span><input v-model="form.unite" maxlength="32" placeholder="ms, %, jobs..."/></label><label class="mon-field"><span>Valeur observee</span><input v-model.number="form.valeurObservee" type="number" step="any"/></label><label class="mon-field mon-field--full"><span>Message</span><textarea v-model="form.message" maxlength="1000" rows="3"></textarea></label><label class="mon-field mon-field--full"><span>Correlation ID</span><input v-model="form.correlationId" maxlength="128"/></label><div class="mon-actions mon-field--full"><button class="mon-btn mon-btn--primary" type="submit">Creer l'alerte</button></div></form></SectionBlock>
<LoadingState v-if="store.state.status==='loading'" title="Alertes en cours" message="Synchronisation avec le backend Monitoring."/><ErrorState v-else-if="store.state.status==='error'" title="Alertes indisponibles" :message="store.state.errorMessage??'Erreur technique.'"/>
<SectionBlock v-else title="Alertes" description="Vue structuree des signaux et seuils."><MonitoringEmptyState v-if="!store.state.alerts.length" title="Aucune alerte" message="Aucun signal d'alerte n'est actuellement expose."/><div v-else class="mon-table-wrap"><table class="mon-table"><thead><tr><th>Indicateur</th><th>Gravite</th><th>Statut</th><th>Valeur</th><th>Seuil</th><th>Date</th><th>Action</th></tr></thead><tbody><tr v-for="a in store.state.alerts" :key="a.identifiant"><td><strong>{{a.indicateur}}</strong><div class="mon-muted">{{a.message}}</div></td><td>{{a.gravite}}</td><td>{{a.statut}}</td><td>{{a.valeurObservee}} {{a.seuil.unite}}</td><td>{{a.seuil.warning}} / {{a.seuil.critical}}</td><td>{{date(a.declencheeLe)}}</td><td><button v-if="canResolve&&a.statut!=='RESOLVED'" class="mon-btn mon-btn--danger" @click="resolve(a.identifiant)">Resoudre</button><span v-else class="mon-muted">Lecture</span></td></tr></tbody></table></div></SectionBlock></PageContainer></template>
<script setup lang="ts">import { reactive } from 'vue';import { RouterLink } from 'vue-router';import { ArrowLeft,RefreshCw } from 'lucide-vue-next';import PageContainer from '../../../shared/layout/PageContainer.vue';import PageHeader from '../../../shared/layout/PageHeader.vue';import SectionBlock from '../../../shared/layout/SectionBlock.vue';import LoadingState from '../../../shared/ui/LoadingState.vue';import ErrorState from '../../../shared/ui/ErrorState.vue';import MonitoringEmptyState from '../components/MonitoringEmptyState.vue';import {hasMonitoringPermission} from '../access/monitoring-access';import {required} from '../validation/monitoring-form.validation';import {useMonitoringStore} from '../stores/monitoring.store';import '../monitoring.css';const store=useMonitoringStore();const canCreate=hasMonitoringPermission('monitoring.alerts.create'),canResolve=hasMonitoringPermission('monitoring.alerts.resolve');const form=reactive({alertId:'',indicateur:'',warning:0,critical:0,unite:'',valeurObservee:0,message:'',correlationId:''});const errors=reactive<{alertId?:string;indicateur?:string}>({});async function create(){errors.alertId=required(form.alertId,'Identifiant');errors.indicateur=required(form.indicateur,'Indicateur');if(errors.alertId||errors.indicateur||form.critical<form.warning)return;await store.creerAlerte({...form})}async function resolve(id:string){if(confirm('Confirmer la resolution de cette alerte ?'))await store.resoudreAlerte(id)}const date=(v:string)=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));</script>
